{
  "pairs": {
    "conflict_5a366395a7365815d6914f16": {
      "classification": "different_products_origins_or_programs",
      "reason": "Claim 1 specifies a 25% rate for UK-origin steel/aluminum articles under a proclamation effective June 2025, noting non-stacking. Claim 2 describes a general 25% tariff on all countries (no exceptions) effective March 2025 under an Executive Order. The claims differ in origin scope (UK vs. all), effective dates (March 2025 vs. June 2025), and legal authority (EO vs. Proclamation).",
      "verification_question": "Does the June 2025 proclamation supersede the March 2025 EO for UK goods, or do they operate concurrently with different rates?"
    },
    "conflict_57184b7231886e8f92aa550d": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 states tariffs do not stack and apply to the full customs value of derivatives as of April 2, 2026. Claim 2 states that Section 232 tariffs apply only to metal content while other tariffs apply to non-metal content based on June/July guidances (context implies August 2025). The claims describe different valuation bases (full value vs. proportional) and timing.",
      "verification_question": "Did the April 2, 2026 proclamation reverse the June/July guidance regarding proportional application of Section 232 tariffs to derivatives?"
    },
    "conflict_faa6a0590fa11d52c10cb9ae": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 asserts 'no tariff stacking' for multi-metal goods and applies Section 232 to the value of metal content only. Claim 2 states that Section 232 tariffs apply to metal content while other additional tariffs apply to non-metal content, implying a form of stacking on different components. The claims differ in their description of how multiple duties interact.",
      "verification_question": "Does the 'no tariff stacking' rule in Claim 1 refer to avoiding duplicate Section 232 rates, or does it preclude applying separate Section 232 and reciprocal tariffs to the same product?"
    },
    "conflict_1b367e34648d2b411e2ed098": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 describes a 10% tariff on the full value of derivatives with at least 85% U.S.-sourced content. Claim 2 states the tariff applies only to the steel content, not the entire value. These represent different valuation bases (full value vs. content value) likely reflecting different policy stages or specific product categories.",
      "verification_question": "Is the 10% full-value rate for U.S.-sourced derivatives a distinct exception to the general rule of content-based valuation described in Claim 2?"
    },
    "conflict_fe8334de248565677b6c0f4d": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 cites a 25% tariff effective March 12, 2025. Claim 2 cites a 50% tariff on most countries affecting fasteners. The claims differ in the applicable rate (25% vs. 50%) and potentially the effective date or scope of application.",
      "verification_question": "Did the tariff rate for fasteners increase from 25% to 50% after March 12, 2025, or do the claims refer to different country-specific rates?"
    }
  }
}
